function checkPrime(arr) {
  // Check if the input is an array of 5 numbers
  if (!Array.isArray(arr) || arr.length !== 5) {
    console.error("Invalid input: array of 5 numbers expected.");
    return;
  }

  // Loop through the array and check each number for primality
  for (let I = 0; I < arr.length; i++) {
    const num = arr[i];

    // Check if the number is a valid integer
    if (!Number.isInteger(num) || num <= 0) {
      console.error(`Invalid prime candidate: ${num} is not a positive integer.`);
      continue;
    }

    // Check if the number is prime
    let isPrime = true;
    for (let j = 2; j * j <= num; j++) {
      if (num % j === 0) {
